import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

/** The checked-in OpenAPI document, the source of truth for the SDK's types. */
export const OPENAPI_PATH = fileURLToPath(
  new URL("../../../spec/developer-v1.openapi.json", import.meta.url),
);

/** Where the generated types are committed. */
export const GENERATED_PATH = fileURLToPath(new URL("../src/generated/api.ts", import.meta.url));

const BANNER = `/**
 * GENERATED FILE - DO NOT EDIT.
 * Generated by \`bun run generate\` from spec/developer-v1.openapi.json.
 */

`;

/**
 * The API documents `additionalProperties: true` on its messages so clients ignore fields added within v1.
 * Left in, the generator adds `& { [key: string]: unknown }` to every type and a typo in a field name compiles.
 * Dropping it types the fields the API documents today; unknown fields still arrive at runtime and are ignored.
 */
function stripOpenObjects(node: unknown): void {
  if (Array.isArray(node)) {
    node.forEach(stripOpenObjects);
  } else if (node && typeof node === "object") {
    const obj = node as Record<string, unknown>;
    if (obj["additionalProperties"] === true) delete obj["additionalProperties"];
    Object.values(obj).forEach(stripOpenObjects);
  }
}

/** Generates the TypeScript declarations for the checked-in OpenAPI document. */
export async function generateTypes(): Promise<string> {
  const schema = JSON.parse(readFileSync(OPENAPI_PATH, "utf8"));
  stripOpenObjects(schema);
  const ast = await openapiTS(schema, { alphabetize: true });
  return BANNER + astToString(ast);
}
